**کامپوننت ModalWrapper (Client Component):**
```javascript
// components/ModalWrapper.js
'use client';

import { useRouter } from 'next/navigation';
import { useEffect, useRef } from 'react';

export default function ModalWrapper({ children }) {
  const router = useRouter();
  const dialogRef = useRef(null);

  useEffect(() => {
    // باز کردن مودال با متد showModal برای مدیریت Focus Trap
    dialogRef.current?.showModal();
  }, []);

  function handleClose() {
    // بستن مودال و بازگشت به صفحه قبل (فید)
    router.back();
  }

  return (
    <dialog
      ref={dialogRef}
      className="fixed inset-0 z-50 backdrop:bg-black/50 rounded-xl shadow-2xl"
      onClose={handleClose}
    >
      <div className="p-6">
        <button onClick={handleClose} className="absolute top-2 right-2">
          ✕
        </button>
        {children}
      </div>
    </dialog>
  );
}
```

