// sentry.config.js (فایل پیکربندی)
import { init } from '@sentry/nextjs';

init({
  dsn: process.env.SENTRY_DSN,
  tracesSampleRate: 0.1, // فقط ۱۰٪ درخواست‌ها Trace شوند
  environment: process.env.NODE_ENV,
  beforeSend(event) {
    // حذف اطلاعات حساس قبل از ارسال
